          "key": { "type": "string", "description": "For a family: $arg:<name>, the argument that names the member." },
          "action": { "type": "string" },
          "params": { "type": "object", "additionalProperties": { "type": "string", "description": "$arg:<name>, or a constant." } },
          "returns": { "enum": ["verdict", "state", "nothing"], "description": "verdict (the default): { ok: true } or { ok: false, reason }." }
        }
      }
    },
    "queries": {
      "type": "object",
      "description": "Each host query: the instance it reads and the fields it returns, renamed as the interface names them.",
      "additionalProperties": {
        "type": "object",
        "required": ["instance", "fields"],
        "additionalProperties": false,
        "properties": {
          "instance": { "type": "string", "description": "An instance name, the name of a family, or $arg:<name> for an argument that names an instance created with the host." },
