import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const fresh = async () => {
  const h: any = await createHost();
  return h;
};
const effectsOf = async (h: any, p: string) => (await h.pendingEffects()).filter((e: any) => e.from === p);

test('authorize, approve, capture, refund', async () => {
  const h = await fresh();
  assert.deepEqual(await h.payment('p'), null);
  assert.equal((await h.authorize('p', 3)).ok, false);
  assert.equal((await h.authorize('p', 0)).ok, false);
  assert.equal(await h.payment('p'), null);
  assert.deepEqual(await h.authorize('p', 2), { ok: true });
  assert.equal((await h.authorize('p', 1)).ok, false);
  const effs = await effectsOf(h, 'p');
  assert.equal(effs.length, 1);
  assert.equal(effs[0].kind, 'card.authorize');
  assert.deepEqual(effs[0].data, { amount: 2 });
  assert.deepEqual(await h.payment('p'), { status: 'authorizing', authorized: 2, captured: 0, refunded: 0, requests: 1 });
  assert.equal((await h.capture('p', 1)).ok, false);
  await h.completeEffect(effs[0].id, 'ok');
  assert.equal((await h.pendingEffects()).length, 0);
  assert.equal((await h.payment('p')).status, 'authorized');
  assert.equal((await h.capture('p', 3)).ok, false);
  assert.deepEqual(await h.capture('p', 2), { ok: true });
  assert.equal((await h.capture('p', 1)).ok, false);
  assert.equal((await h.void('p')).ok, false);
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.equal((await h.payment('p')).status, 'captured');
  assert.equal((await h.refund('p', 2)).ok, false);
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'refunded', authorized: 2, captured: 2, refunded: 2, requests: 1 });
  assert.equal((await h.refund('p', 1)).ok, false);
  await h.__dispose();
});

test('unknown payment refused', async () => {
  const h = await fresh();
  for (const r of [await h.timedOut('x'), await h.capture('x', 1), await h.void('x'), await h.refund('x', 1)]) assert.equal(r.ok, false);
  assert.equal(await h.payment('x'), null);
  await h.__dispose();
});

test('timeouts, late answers, failure', async () => {
  const h = await fresh();
  await h.authorize('p', 1);
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.equal((await effectsOf(h, 'p')).length, 3);
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'failed', authorized: 1, captured: 0, refunded: 0, requests: 3 });
  assert.equal((await h.timedOut('p')).ok, false);
  const effs = await effectsOf(h, 'p');
  await h.completeEffect(effs[0].id, 'ok');
  assert.equal((await h.payment('p')).status, 'failed');
  assert.equal((await effectsOf(h, 'p')).length, 2);
  await h.__dispose();
});

test('decline, first answer decides, void', async () => {
  const h = await fresh();
  await h.authorize('a', 1);
  await h.timedOut('a');
  const [e1, e2] = await effectsOf(h, 'a');
  await h.completeEffect(e2.id, 'failed');
  assert.equal((await h.payment('a')).status, 'declined');
  await h.completeEffect(e1.id, 'ok');
  assert.equal((await h.payment('a')).status, 'declined');

  await h.authorize('b', 2);
  const [eb] = await effectsOf(h, 'b');
  await h.completeEffect(eb.id, 'ok');
  assert.deepEqual(await h.void('b'), { ok: true });
  assert.deepEqual(await h.payment('b'), { status: 'voided', authorized: 2, captured: 0, refunded: 0, requests: 1 });
  assert.equal((await h.capture('b', 1)).ok, false);
  await h.__dispose();
});

